import{_ as l,c as e,o as r,a3 as a}from"./chunks/framework.czLORLkK.js";const p=JSON.parse('{"title":"SyncBoot 제품소개서 (Product Introduction Deck)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/downloads/SyncBoot_소개_v1.0"}]]},"headers":[],"relativePath":"public/downloads/SyncBoot_소개_v1.0.md","filePath":"public/downloads/SyncBoot_소개_v1.0.md","lastUpdated":1793206480000}'),i={name:"public/downloads/SyncBoot_소개_v1.0.md"};function n(o,t,s,d,g,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="syncboot-제품소개서-product-introduction-deck" tabindex="-1">SyncBoot 제품소개서 (Product Introduction Deck) <a class="header-anchor" href="#syncboot-제품소개서-product-introduction-deck" aria-label="Permalink to “SyncBoot 제품소개서 (Product Introduction Deck)”">​</a></h1><blockquote><p><strong>Empasy SyncSeries AI Autonomous Operations Ecosystem</strong><br> 문서 버전: 2026.08 (v1.0) | 작성: 엠파시 솔루션개발팀</p></blockquote><hr><h2 id="slide-01-표지-syncboot" tabindex="-1">[Slide 01] 표지: SyncBoot <a class="header-anchor" href="#slide-01-표지-syncboot" aria-label="Permalink to “[Slide 01] 표지: SyncBoot”">​</a></h2><ul><li><strong>카테고리</strong>: AI AGENT · ENTERPRISE BACKEND &amp; LOW-CODE FRAMEWORK</li><li><strong>제품명</strong>: <strong>SyncBoot</strong></li><li><strong>슬로건</strong>: AI Agent 기반 엔터프라이즈 백엔드 &amp; 로우코드 풀스택 프레임워크</li><li><strong>핵심 키워드</strong>: <code>Context-Aware Backend Agent · Dynamic DDL &amp; CRUD Generator · RBAC Multi-Tenant Security · High-Performance Batch</code></li><li><strong>핵심 에이전트</strong>: <code>Domain Operator Agent · Schema Architect Agent · Security IAM Agent · MCP Dispatcher Agent · Batch Orchestrator Agent</code></li><li><strong>발행처</strong>: Empasy. 엠파시 솔루션개발팀</li></ul><hr><h2 id="slide-02-02-·-syncboot-란-무-엇-을-하-는-프-로-그-램-인-가" tabindex="-1">[Slide 02] 02 · SyncBoot 란 (무 엇 을 하 는 프 로 그 램 인 가) <a class="header-anchor" href="#slide-02-02-·-syncboot-란-무-엇-을-하-는-프-로-그-램-인-가" aria-label="Permalink to “[Slide 02] 02 · SyncBoot 란 (무 엇 을 하 는 프 로 그 램 인 가)”">​</a></h2><h3 id="도메인-데이터의-안전한-자율-운영과-로우코드-개발-생산성을-극대화합니다" tabindex="-1"><strong>도메인 데이터의 안전한 자율 운영과 로우코드 개발 생산성을 극대화합니다.</strong> <a class="header-anchor" href="#도메인-데이터의-안전한-자율-운영과-로우코드-개발-생산성을-극대화합니다" aria-label="Permalink to “도메인 데이터의 안전한 자율 운영과 로우코드 개발 생산성을 극대화합니다.”">​</a></h3><p>엔터프라이즈 백엔드 시스템을 새로 구축할 때도 쓰고, 이미 운영 중인 대규모 데이터베이스를 관리할 때도 씁니다. 도메인 자율 운영과 스키마 거버넌스를 중심으로 설명합니다.</p><blockquote><p><strong>한 문장으로 요약</strong>: 시스템 도메인 맥락을 인지하여 안전한 CRUD 운영, 지능형 스키마 설계, RBAC 보안 통제 및 고성능 배치를 자율 수행하는 AI 백엔드 프레임워크</p></blockquote><ul><li><strong>안전한 DDL 승인 체계</strong>: DB 스키마 변경 시 개발자 사전 승인(HITL) 필수 보장</li><li><strong>정밀한 데이터 격리</strong>: Multi-Tenant 완벽 분리 및 컬럼 단위 세분화 RBAC 통제</li><li><strong>소스코드 무결성 보존</strong>: 운영 CRUD와 소스코드 수정을 엄격히 분리하여 안전성 확보</li></ul><p><strong>주요 기능 4대 축</strong>:</p><ol><li><strong>도메인 CRUD 자율 운영 및 쿼리 실행</strong>: 구축된 시스템의 비즈니스 도메인을 인지하여 안전한 데이터 조작과 트랜잭션을 자율 처리합니다.</li><li><strong>지능형 스키마 설계 및 DDL 제안</strong>: 자연어 요구사항을 분석하여 정규화된 3-File 표준 DDL을 설계하고 개발자에게 승인을 요청합니다.</li><li><strong>로우코드 API &amp; 서비스 템플릿 생성</strong>: Entity 정의만으로 Controller, Service, Mapper, Vue UI 코드를 원클릭으로 자동 생성합니다.</li><li><strong>멀티테넌트 및 세분화 IAM 보안 관리</strong>: 테넌트별 데이터베이스 격리, 데이터 마스킹, 권한 감사 로그를 엔터프라이즈 레벨로 통제합니다.</li></ol><hr><h2 id="slide-03-03-·-전-체-구-조-한-눈-에-보-기" tabindex="-1">[Slide 03] 03 · 전 체 구 조 (한 눈 에 보 기) <a class="header-anchor" href="#slide-03-03-·-전-체-구-조-한-눈-에-보-기" aria-label="Permalink to “[Slide 03] 03 · 전 체 구 조 (한 눈 에 보 기)”">​</a></h2><h3 id="서비스-개발-요청이-오기-전에-도메인-스키마와-보안-정책을-미리-정립합니다" tabindex="-1"><strong>서비스 개발 요청이 오기 전에, 도메인 스키마와 보안 정책을 미리 정립합니다.</strong> <a class="header-anchor" href="#서비스-개발-요청이-오기-전에-도메인-스키마와-보안-정책을-미리-정립합니다" aria-label="Permalink to “서비스 개발 요청이 오기 전에, 도메인 스키마와 보안 정책을 미리 정립합니다.”">​</a></h3><p>SyncBoot의 워크플로우는 세 가지 단계로 나뉩니다. 도메인을 모델링하고 3-File 스키마를 설계하며(A), 로우코드 엔진과 AI 에이전트로 서비스를 고속 실행하고(B), 분산 로그 모니터링 및 감사 이력으로 시스템을 안정화합니다(C).</p><table tabindex="0"><thead><tr><th style="text-align:left;">단계</th><th style="text-align:left;">구분</th><th style="text-align:left;">주요 내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>PRE-PROCESS</strong></td><td style="text-align:left;">A. 도메인 모델링 및 스키마 설계</td><td style="text-align:left;">자연어 기반 도메인 엔티티 분석 — 비즈니스 명세를 ERD 및 테이블 구조로 변환</td></tr><tr><td style="text-align:left;"><strong>PRE-PROCESS</strong></td><td style="text-align:left;">A. 도메인 모델링 및 스키마 설계</td><td style="text-align:left;">3-File DB 스키마 표준 수립 — init.sql / 도메인.sql / sample.sql 자동 분리</td></tr><tr><td style="text-align:left;"><strong>PRE-PROCESS</strong></td><td style="text-align:left;">A. 도메인 모델링 및 스키마 설계</td><td style="text-align:left;">테넌트 격리 및 인덱스 정책 수립 — 대용량 트래픽 대비 파티셔닝 및 인덱스 최적화</td></tr><tr><td style="text-align:left;"><strong>CORE EXECUTION</strong></td><td style="text-align:left;">B. 로우코드 실행 및 IAM 통제</td><td style="text-align:left;">1. 다섯 에이전트 협업 실행 — 운영-스키마-보안-MCP-배치가 유기적으로 결합</td></tr><tr><td style="text-align:left;"><strong>CORE EXECUTION</strong></td><td style="text-align:left;">B. 로우코드 실행 및 IAM 통제</td><td style="text-align:left;">2. 로우코드 풀스택 자동 빌드 — Spring Boot + Vue3 표준 보일러플레이트 고속 생성</td></tr><tr><td style="text-align:left;"><strong>CORE EXECUTION</strong></td><td style="text-align:left;">B. 로우코드 실행 및 IAM 통제</td><td style="text-align:left;">3. 세분화 RBAC 및 데이터 마스킹 — JWT 토큰 및 역할별 데이터 접근 권한 실시간 감시</td></tr><tr><td style="text-align:left;"><strong>POST-PROCESS</strong></td><td style="text-align:left;">C. 분산 로깅 및 감사 추적</td><td style="text-align:left;">클러스터 분산 로그 자율 수집 — 장애 시 에이전트가 서버 로그를 직접 추출하여 전달</td></tr><tr><td style="text-align:left;"><strong>POST-PROCESS</strong></td><td style="text-align:left;">C. 분산 로깅 및 감사 추적</td><td style="text-align:left;">대용량 배치 및 스케줄러 모니터링 — Quartz/Spring Batch 작업 상태 실시간 추적</td></tr><tr><td style="text-align:left;"><strong>POST-PROCESS</strong></td><td style="text-align:left;">C. 분산 로깅 및 감사 추적</td><td style="text-align:left;">데이터 리니지 &amp; 변경 감사 이력 — 누가 언제 어떤 데이터를 수정했는지 완벽 보존</td></tr></tbody></table><hr><h2 id="slide-04-04-·-핵-심-에-이-전-트-a-g-e-n-t-s" tabindex="-1">[Slide 04] 04 · 핵 심 에 이 전 트 (A G E N T S) <a class="header-anchor" href="#slide-04-04-·-핵-심-에-이-전-트-a-g-e-n-t-s" aria-label="Permalink to “[Slide 04] 04 · 핵 심 에 이 전 트 (A G E N T S)”">​</a></h2><h3 id="에이전트-다섯이-엔터프라이즈-백엔드를-자율-운영합니다" tabindex="-1"><strong>에이전트 다섯이 엔터프라이즈 백엔드를 자율 운영합니다.</strong> <a class="header-anchor" href="#에이전트-다섯이-엔터프라이즈-백엔드를-자율-운영합니다" aria-label="Permalink to “에이전트 다섯이 엔터프라이즈 백엔드를 자율 운영합니다.”">​</a></h3><p>요청 한 건이 들어오면 각자 맡은 역할을 수행하고 결과를 반환합니다. 런타임 운영과 개발 승인이 엄격히 통제됩니다.</p><ul><li><strong>01 Domain Operator Agent (도메인 CRUD 자율 운영)</strong> (<code>AI 사용 · 자동 수행</code>): 자신이 상주하는 시스템 도메인을 인지하여 안전한 데이터 CRUD 및 비즈니스 쿼리를 실행합니다.</li><li><strong>02 Schema Architect Agent (지능형 DDL &amp; 스키마 설계)</strong> (<code>AI 사용 · 확인 1회</code>): 새로운 데이터 구조 요구 시 정규화된 테이블 DDL을 제안하고 개발자에게 승인을 요청합니다.</li><li><strong>03 Security IAM Agent (RBAC 권한 &amp; 테넌트 격리)</strong> (<code>AI 사용 · 자동 수행</code>): 사용자 역할별 메뉴/API 접근 제어, 민감정보 마스킹 및 멀티테넌트 침범을 실시간 감시합니다.</li><li><strong>04 MCP Dispatcher Agent (표준 MCP 서비스 연동)</strong> (<code>AI 사용 · 자동 수행</code>): SyncVerse 및 타 에이전트와 A2A 통신을 위한 표준 Tool(스키마 조회, 로그 수집 등)을 제공합니다.</li><li><strong>05 Batch Orchestrator Agent (고성능 배치 &amp; 스케줄러)</strong> (<code>AI 사용 · 확인 1회</code>): 대용량 데이터 집계 및 주기적 Quartz 배치 작업을 최적의 시간에 분산 스케줄링합니다.</li></ul><blockquote><p><strong>[확장성] 고객의 특화 비즈니스(예: 금융 정산, 물류 트래킹, 결제 게이트웨이 등)에 맞춤형 백엔드 워커 에이전트를 손쉽게 추가하여 무한히 확장할 수 있습니다.</strong></p></blockquote><hr><h2 id="slide-05-05-·-유-지-보-수-현-장-무-엇-이-힘-든-가" tabindex="-1">[Slide 05] 05 · 유 지 보 수 현 장 (무 엇 이 힘 든 가) <a class="header-anchor" href="#slide-05-05-·-유-지-보-수-현-장-무-엇-이-힘-든-가" aria-label="Permalink to “[Slide 05] 05 · 유 지 보 수 현 장 (무 엇 이 힘 든 가)”">​</a></h2><h3 id="단순-crud-코딩과-db-스키마-관리에-개발-리소스가-낭비됩니다" tabindex="-1"><strong>단순 CRUD 코딩과 DB 스키마 관리에 개발 리소스가 낭비됩니다.</strong> <a class="header-anchor" href="#단순-crud-코딩과-db-스키마-관리에-개발-리소스가-낭비됩니다" aria-label="Permalink to “단순 CRUD 코딩과 DB 스키마 관리에 개발 리소스가 낭비됩니다.”">​</a></h3><p>엔터프라이즈 백엔드는 단순 반복 작업이 많고, 스키마 변경 사고나 권한 누락 시 치명적인 비즈니스 장애로 이어집니다.</p><ol><li><strong>단순 반복 CRUD API 개발에 백엔드 리소스 40% 소모</strong>: 매 프로젝트마다 동일한 컨트롤러, 서비스, DTO, 매퍼 코딩을 반복하며 고급 개발 리소스 낭비</li><li><strong>DB 스키마 변경 시 영향도 파악 및 마이그레이션 사고</strong>: 컬럼 하나 추가/수정 시 기존 쿼리와 연관 API 영향도를 파악하지 못해 런타임 에러 발생</li><li><strong>멀티테넌트 및 세분화 RBAC 권한 구현의 높은 난이도</strong>: 고객사별 데이터 분리 및 역할별 세부 권한 로직을 처음부터 구현하느라 수개월 소요</li><li><strong>대용량 배치 작업 실패 시 원인 파악 및 수작업 재처리 난항</strong>: 야간 배치 장애 발생 시 수백만 건의 데이터 중 어느 지점에서 실패했는지 추적이 어려움</li><li><strong>장애 발생 시 분산 클러스터 서버 로그 수집 지연</strong>: 서버가 수십 대로 분산된 환경에서 특정 트랜잭션의 로그를 모으는 데 많은 시간 소요</li></ol><hr><h2 id="slide-06-06-·-역-할-분-담-a-i-vs-사-람" tabindex="-1">[Slide 06] 06 · 역 할 분 담 (A I vs 사 람) <a class="header-anchor" href="#slide-06-06-·-역-할-분-담-a-i-vs-사-람" aria-label="Permalink to “[Slide 06] 06 · 역 할 분 담 (A I  vs  사 람)”">​</a></h2><h3 id="ai는-스키마-설계와-crud-운영을-맡습니다-ddl-승인은-개발자가-합니다" tabindex="-1"><strong>AI는 스키마 설계와 CRUD 운영을 맡습니다. DDL 승인은 개발자가 합니다.</strong> <a class="header-anchor" href="#ai는-스키마-설계와-crud-운영을-맡습니다-ddl-승인은-개발자가-합니다" aria-label="Permalink to “AI는 스키마 설계와 CRUD 운영을 맡습니다. DDL 승인은 개발자가 합니다.”">​</a></h3><p>AI에게 &#39;주문 정산 도메인 스키마를 설계하고 데이터를 운영해라&#39;라고 하면 잘합니다. 실제 프로덕션 DB 구조 변경은 엔지니어가 승인합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">01 SCHEMA / CODE GEN (스키마 모델링 및 보일러플레이트 자동화)</th><th style="text-align:left;">02 HUMAN IN THE LOOP (백엔드 아키텍트 (사람))</th><th style="text-align:left;">03 DOMAIN OPERATOR / IAM (안전한 데이터 런타임 운영 및 보안)</th></tr></thead><tbody><tr><td style="text-align:left;">3-File 표준 DDL 및 인덱스 구조 자동 생성</td><td style="text-align:left;"><strong>AI가 제안한 DDL 및 스키마 변경안 최종 승인</strong></td><td style="text-align:left;">권한 검증된 트랜잭션 CRUD 자율 실행</td></tr><tr><td style="text-align:left;">Spring Boot + Vue3 풀스택 코드 생성</td><td style="text-align:left;"><strong>멀티테넌트 격리 정책 및 보안 규칙 확정</strong></td><td style="text-align:left;">클러스터 서버 로그 직접 수집 및 자가진단</td></tr><tr><td style="text-align:left;">도메인 비즈니스 규칙 및 검증 로직 수립</td><td style="text-align:left;"><strong>가장 핵심적인 안전 검증 지점</strong></td><td style="text-align:left;">배치 스케줄링 및 데이터 리니지 감사 기록</td></tr></tbody></table><blockquote><p><strong>핵심 요약</strong>: SyncBoot를 쓰면: 개발자가 매번 지루한 CRUD 코딩과 위험한 DB 마이그레이션에 시간을 뺏기지 않고, AI가 제안한 정규화 DDL을 &#39;승인&#39;하기만 하면 견고한 엔터프라이즈 백엔드가 즉시 가동됩니다.</p></blockquote><hr><h2 id="slide-07-07-·-화-면-1-·-도메인-통합-관제-샘플-화면" tabindex="-1">[Slide 07] 07 · 화 면 1 · 도메인 통합 관제 (샘플 화면) <a class="header-anchor" href="#slide-07-07-·-화-면-1-·-도메인-통합-관제-샘플-화면" aria-label="Permalink to “[Slide 07] 07 · 화 면 1 · 도메인 통합 관제 (샘플 화면)”">​</a></h2><h3 id="백엔드-시스템-전반의-상태와-도메인-데이터를-한눈에-관제합니다" tabindex="-1"><strong>백엔드 시스템 전반의 상태와 도메인 데이터를 한눈에 관제합니다.</strong> <a class="header-anchor" href="#백엔드-시스템-전반의-상태와-도메인-데이터를-한눈에-관제합니다" aria-label="Permalink to “백엔드 시스템 전반의 상태와 도메인 데이터를 한눈에 관제합니다.”">​</a></h3><p>엔터프라이즈 서버 인스턴스, DB 커넥션 풀, Redis 캐시 및 도메인 트랜잭션을 실시간 모니터링합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>도메인 엔티티 헬스체크</strong>: 등록된 도메인 테이블별 레코드 수, 트랜잭션 TPS 및 지연시간 실시간 표시</li><li><strong>JVM &amp; 리소스 메트릭 모니터링</strong>: 힙 메모리 사용량, CPU 로드, GC 발생 횟수 및 HikariCP 풀 상태 감시</li><li><strong>활성 트랜잭션 추적</strong>: 현재 실행 중인 롱러닝 쿼리 및 락(Lock) 경합 상태를 실시간 감지</li><li><strong>에이전트 런타임 상태 확인</strong>: SyncBoot 내 상주하는 5개 에이전트의 구동 상태 및 메모리 확인</li><li><strong>Redis 캐시 히트율 분석</strong>: 도메인 쿼리 캐시 히트율 및 TTL 만료 정책 실시간 시각화</li><li><strong>비상 정지 및 서킷 브레이커</strong>: 트래픽 폭증 시 특정 도메인 API를 안전하게 차단하는 서킷 브레이커 제어</li></ol><hr><h2 id="slide-08-08-·-화-면-2-·-지능형-스키마-스튜디오-샘플-화면" tabindex="-1">[Slide 08] 08 · 화 면 2 · 지능형 스키마 스튜디오 (샘플 화면) <a class="header-anchor" href="#slide-08-08-·-화-면-2-·-지능형-스키마-스튜디오-샘플-화면" aria-label="Permalink to “[Slide 08] 08 · 화 면 2 · 지능형 스키마 스튜디오 (샘플 화면)”">​</a></h2><h3 id="자연어-요구사항을-입력하면-3-file-표준-ddl이-완성됩니다" tabindex="-1"><strong>자연어 요구사항을 입력하면 3-File 표준 DDL이 완성됩니다.</strong> <a class="header-anchor" href="#자연어-요구사항을-입력하면-3-file-표준-ddl이-완성됩니다" aria-label="Permalink to “자연어 요구사항을 입력하면 3-File 표준 DDL이 완성됩니다.”">​</a></h3><p>초보자도 알기 쉬운 ERD 시각화와 함께 3-File(<code>init.sql</code>, <code>도메인.sql</code>, <code>sample.sql</code>) 스크립트를 자동 생성합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>자연어 기반 테이블 설계</strong>: &#39;정기 결제 구독 테이블 만들어줘&#39; 입력 시 DDL 자동 생성</li><li><strong>3-File SQL 구조 자동 분리</strong>: 플랫폼 기본(init), 도메인 특화(domain), 개발용 샘플(sample)로 분할</li><li><strong>대화형 ERD 비주얼 뷰어</strong>: 테이블 간 PK/FK 관계와 인덱스 구조를 다이어그램으로 시각화</li><li><strong>스키마 변경 영향도 분석</strong>: 컬럼 삭제/수정 시 영향을 받는 쿼리와 서비스 목록 사전 탐색</li><li><strong>마이그레이션 DDL 승인 콘솔</strong>: 개발자가 검토 후 원클릭 승인 시 실제 DB에 안전하게 DDL 반영</li><li><strong>멀티 DB 방언(Dialect) 지원</strong>: MySQL, PostgreSQL, Oracle, MariaDB 문법 자동 변환</li></ol><hr><h2 id="slide-09-09-·-화-면-3-·-로우코드-api-생성기-샘플-화면" tabindex="-1">[Slide 09] 09 · 화 면 3 · 로우코드 API 생성기 (샘플 화면) <a class="header-anchor" href="#slide-09-09-·-화-면-3-·-로우코드-api-생성기-샘플-화면" aria-label="Permalink to “[Slide 09] 09 · 화 면 3 · 로우코드 API 생성기 (샘플 화면)”">​</a></h2><h3 id="테이블-선택-한-번으로-controller부터-vue-화면까지-자동-생성됩니다" tabindex="-1"><strong>테이블 선택 한 번으로 Controller부터 Vue 화면까지 자동 생성됩니다.</strong> <a class="header-anchor" href="#테이블-선택-한-번으로-controller부터-vue-화면까지-자동-생성됩니다" aria-label="Permalink to “테이블 선택 한 번으로 Controller부터 Vue 화면까지 자동 생성됩니다.”">​</a></h3><p>Spring Boot 3 + MyBatis/JPA 백엔드 코드와 Ant Design Vue 기반 관리자 UI 코드를 원클릭으로 패키징합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>풀스택 원클릭 코드 생성</strong>: Entity, DTO, Mapper, Service, Controller, Vue 화면 일괄 생성</li><li><strong>고급 검색 &amp; 필터 조건 설정</strong>: 날짜 범위, 다중 셀렉트, 키워드 검색 등 필터 조건을 UI에서 지정</li><li><strong>입력 폼 유효성 검증 자동화</strong>: 필수값, 이메일, 전화번호, 정규식 검증 로직을 프론트/백엔드에 동시 적용</li><li><strong>Swagger / OpenAPI 3.0 연동</strong>: 생성된 모든 REST API의 인터랙티브 문서 자동 생성 및 테스트 샌드박스</li><li><strong>엑셀 대용량 다운로드/업로드</strong>: EasyExcel 기반 10만 건 이상 대용량 엑셀 처리 코드 기본 탑재</li><li><strong>Git 브랜치 자동 커밋</strong>: 생성된 코드를 지정된 작업 브랜치로 자동 커밋 및 PR 생성</li></ol><hr><h2 id="slide-10-10-·-화-면-4-·-멀티테넌트-iam-샘플-화면" tabindex="-1">[Slide 10] 10 · 화 면 4 · 멀티테넌트 &amp; IAM (샘플 화면) <a class="header-anchor" href="#slide-10-10-·-화-면-4-·-멀티테넌트-iam-샘플-화면" aria-label="Permalink to “[Slide 10] 10 · 화 면 4 · 멀티테넌트 &amp; IAM (샘플 화면)”">​</a></h2><h3 id="기업-고객별-테넌트-격리와-세분화-rbac-권한을-완벽-통제합니다" tabindex="-1"><strong>기업 고객별 테넌트 격리와 세분화 RBAC 권한을 완벽 통제합니다.</strong> <a class="header-anchor" href="#기업-고객별-테넌트-격리와-세분화-rbac-권한을-완벽-통제합니다" aria-label="Permalink to “기업 고객별 테넌트 격리와 세분화 RBAC 권한을 완벽 통제합니다.”">​</a></h3><p>테넌트별 데이터베이스/스키마 격리와 함께 메뉴, 버튼, 데이터 컬럼 단위의 정밀한 접근 제어를 설정합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>멀티테넌트 격리 관리자</strong>: 테넌트별 독립 DB 또는 공유 DB 테넌트 ID 컬럼 방식 자유 선택</li><li><strong>트리형 RBAC 역할/메뉴 매핑</strong>: 부서 및 직급별 세부 메뉴 접근 권한과 버튼 클릭 권한 드래그 매핑</li><li><strong>컬럼 단위 동적 데이터 마스킹</strong>: 개인정보(전화번호, 계좌번호 등)를 직급에 따라 마스킹 처리</li><li><strong>JWT &amp; Refresh Token 세션 관리</strong>: 실시간 로그인 사용자 세션 확인 및 이상 접속자 원격 강제 로그아웃</li><li><strong>행 단위(Row-Level) 데이터 보안</strong>: 자신이 속한 지점이나 팀의 데이터만 조회되도록 SQL 자동 주입</li><li><strong>SSO 및 소셜 OAuth 연동</strong>: SAML, OIDC, 사내 Active Directory 및 Google SSO 원클릭 연동</li></ol><hr><h2 id="slide-11-11-·-화-면-5-·-배치-작업-스케줄러-샘플-화면" tabindex="-1">[Slide 11] 11 · 화 면 5 · 배치 &amp; 작업 스케줄러 (샘플 화면) <a class="header-anchor" href="#slide-11-11-·-화-면-5-·-배치-작업-스케줄러-샘플-화면" aria-label="Permalink to “[Slide 11] 11 · 화 면 5 · 배치 &amp; 작업 스케줄러 (샘플 화면)”">​</a></h2><h3 id="대용량-배치-작업의-분산-실행과-실패-시-재처리를-자동화합니다" tabindex="-1"><strong>대용량 배치 작업의 분산 실행과 실패 시 재처리를 자동화합니다.</strong> <a class="header-anchor" href="#대용량-배치-작업의-분산-실행과-실패-시-재처리를-자동화합니다" aria-label="Permalink to “대용량 배치 작업의 분산 실행과 실패 시 재처리를 자동화합니다.”">​</a></h3><p>Spring Batch와 Quartz 기반의 대규모 데이터 처리 작업을 시간표로 관리하고 실행 상태를 실시간 추적합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>시각적 크론(Cron) 스케줄러</strong>: 복잡한 크론 표현식을 GUI 시간표로 직관적으로 설정 및 검증</li><li><strong>스텝별 청크(Chunk) 진행률 추적</strong>: 수백만 건 데이터 배치 처리 시 읽기/가공/쓰기 진행률 실시간 표시</li><li><strong>실패 스텝 자동 재시도 및 Skip</strong>: 네트워크 지연 시 지수 백오프(Exponential Backoff) 재시도 자동 수행</li><li><strong>배치 파라미터 동적 주입</strong>: 실행 시점의 날짜 변수 및 런타임 파라미터를 유연하게 전달</li><li><strong>배치 실행 이력 및 락 관리</strong>: 과거 실행 성공/실패 통계와 중복 실행 방지 분산 락(Redis Lock) 제어</li><li><strong>장애 발생 시 관리자 긴급 알림</strong>: 배치 실패 시 스택트레이스를 분석하여 담당자 Slack/Email 즉시 통보</li></ol><hr><h2 id="slide-12-12-·-화-면-6-·-분산-서버-로그-자가진단-샘플-화면" tabindex="-1">[Slide 12] 12 · 화 면 6 · 분산 서버 로그 &amp; 자가진단 (샘플 화면) <a class="header-anchor" href="#slide-12-12-·-화-면-6-·-분산-서버-로그-자가진단-샘플-화면" aria-label="Permalink to “[Slide 12] 12 · 화 면 6 · 분산 서버 로그 &amp; 자가진단 (샘플 화면)”">​</a></h2><h3 id="클러스터에-분산된-수십-대-서버의-로그를-에이전트가-직접-수집합니다" tabindex="-1"><strong>클러스터에 분산된 수십 대 서버의 로그를 에이전트가 직접 수집합니다.</strong> <a class="header-anchor" href="#클러스터에-분산된-수십-대-서버의-로그를-에이전트가-직접-수집합니다" aria-label="Permalink to “클러스터에 분산된 수십 대 서버의 로그를 에이전트가 직접 수집합니다.”">​</a></h3><p>장애 발생 시 SyncVerse의 요청에 따라 에이전트가 인스턴스 서버 로그를 자율 추출하여 원인을 진단합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>에이전트 직접 질의 로그 수집</strong>: 중앙 저장소 장애 시에도 에이전트가 서버 로컬 로그를 즉시 추출</li><li><strong>Trace ID 기반 분산 트랜잭션 추적</strong>: 클라이언트 요청부터 DB 쿼리까지 이어지는 전체 콜체인 시각화</li><li><strong>AI 자연어 에러 원인 분석</strong>: 복잡한 Java NullPointerException의 원인을 한글로 명확히 해설</li><li><strong>Elasticsearch / OpenSearch 연동</strong>: 대규모 로그 검색을 위한 중앙 검색 엔진 옵션 완벽 지원</li><li><strong>실시간 로그 스트리밍 (Tail)</strong>: 서버 터미널 접속 없이 웹 콘솔에서 실시간 로그 흐름 모니터링</li><li><strong>민감 로그 자동 마스킹</strong>: 로그 파일에 기록되는 비밀번호, 토큰 등 개인정보 자동 필터링</li></ol><hr><h2 id="slide-13-13-·-화-면-7-·-데이터-리니지-감사-이력-샘플-화면" tabindex="-1">[Slide 13] 13 · 화 면 7 · 데이터 리니지 &amp; 감사 이력 (샘플 화면) <a class="header-anchor" href="#slide-13-13-·-화-면-7-·-데이터-리니지-감사-이력-샘플-화면" aria-label="Permalink to “[Slide 13] 13 · 화 면 7 · 데이터 리니지 &amp; 감사 이력 (샘플 화면)”">​</a></h2><h3 id="데이터의-생성부터-변경-삭제까지-모든-흐름을-영구-추적합니다" tabindex="-1"><strong>데이터의 생성부터 변경, 삭제까지 모든 흐름을 영구 추적합니다.</strong> <a class="header-anchor" href="#데이터의-생성부터-변경-삭제까지-모든-흐름을-영구-추적합니다" aria-label="Permalink to “데이터의 생성부터 변경, 삭제까지 모든 흐름을 영구 추적합니다.”">​</a></h3><p>엔터프라이즈 컴플라이언스 준수를 위해 모든 도메인 데이터의 전후 상태(Before/After)와 변경자를 완벽 기록합니다.</p><p><strong>이 화면에서 할 수 있는 일 (6대 기능)</strong>:</p><ol><li><strong>Before/After 데이터 Diff 뷰</strong>: 테이블 레코드 수정 전과 후의 변경된 컬럼값을 색상으로 대조</li><li><strong>작업자 &amp; 클라이언트 IP 추적</strong>: 누가, 어느 PC에서, 어떤 권한으로 조작했는지 감사 로그 보존</li><li><strong>데이터 상태 원클릭 롤백 (Revert)</strong>: 관리자 실수로 잘못 변경된 레코드를 이전 상태로 즉각 복구</li><li><strong>도메인 데이터 리니지 맵</strong>: 데이터가 어느 배치나 서비스 API를 거쳐 흘러갔는지 계보 시각화</li><li><strong>위변조 방지 해시 체인</strong>: 감사 로그의 임의 삭제나 수정을 방지하는 블록체인형 해시 검증</li><li><strong>감사 증적 보고서 다운로드</strong>: ISMS, 금융보안원 등 정보보호 인증 심사용 감사 리포트 자동 생성</li></ol><hr><h2 id="slide-14-14-·-담-당-자-가-하-는-일-에-이-전-트-와-사-람" tabindex="-1">[Slide 14] 14 · 담 당 자 가 하 는 일 (에 이 전 트 와 사 람) <a class="header-anchor" href="#slide-14-14-·-담-당-자-가-하-는-일-에-이-전-트-와-사-람" aria-label="Permalink to “[Slide 14] 14 · 담 당 자 가  하 는  일 (에 이 전 트 와  사 람)”">​</a></h2><h3 id="개발자가-하는-일은-제안된-스키마를-승인-하는-것입니다" tabindex="-1"><strong>개발자가 하는 일은 제안된 스키마를 &#39;승인&#39;하는 것입니다.</strong> <a class="header-anchor" href="#개발자가-하는-일은-제안된-스키마를-승인-하는-것입니다" aria-label="Permalink to “개발자가 하는 일은 제안된 스키마를 &#39;승인&#39;하는 것입니다.”">​</a></h3><p>도메인을 분석하고, DDL을 설계하며, CRUD를 실행하고 로그를 수집하는 일은 AI 에이전트가 합니다. 개발자는 제안된 스키마 구조가 맞는지만 봐 주시면 됩니다.</p><ol><li><strong>STEP 01 (SCHEMA / CODE GEN)</strong>: 3-File DDL 및 서비스 템플릿 설계 — 자연어 요구사항을 바탕으로 정규화된 테이블 DDL, 인덱스 정책, 로우코드 서비스 코드를 준비해 내놓습니다.</li><li><strong>STEP 02 (주요 역할) (백엔드 엔지니어 (사람))</strong>: DDL과 보안 정책을 승인합니다 — 제안된 DB 스키마 구조와 테넌트 격리 규칙을 검토하고 실제 반영을 승인합니다. 요청 한 건에 한 번 검토합니다.</li><li><strong>STEP 03 (DOMAIN OPERATOR / IAM / BATCH)</strong>: 안전하게 운영하고 감사 로그를 남김 — 승인된 스키마 위에서 비즈니스 CRUD를 자율 운영하고, 배치 작업을 스케줄링하며, 모든 이력을 기록합니다.</li></ol><ul><li><strong>정교한 스키마 거버넌스</strong>: DB 변경 사고가 발생하지 않습니다 (모든 DDL 변경이 3-File 표준 규칙과 개발자 승인 절차를 거치기 때문입니다.)</li><li><strong>투명한 책임 추적</strong>: 누가 어떤 데이터를 바꿨는지 남습니다 (데이터 조작자와 AI 에이전트의 실행 로그가 타임스탬프와 함께 완벽히 기록됩니다.)</li></ul><hr><h2 id="slide-15-15-·-무-엇-이-달-라-지-나-지-금-vs-도-입-후" tabindex="-1">[Slide 15] 15 · 무 엇 이 달 라 지 나 (지 금 vs . 도 입 후) <a class="header-anchor" href="#slide-15-15-·-무-엇-이-달-라-지-나-지-금-vs-도-입-후" aria-label="Permalink to “[Slide 15] 15 · 무 엇 이  달 라 지 나 (지 금  vs .  도 입  후)”">​</a></h2><h3 id="지금-하시는-일과-비교하면-이렇습니다" tabindex="-1"><strong>지금 하시는 일과 비교하면 이렇습니다.</strong> <a class="header-anchor" href="#지금-하시는-일과-비교하면-이렇습니다" aria-label="Permalink to “지금 하시는 일과 비교하면 이렇습니다.”">​</a></h3><p>일이 완전히 없어지지는 않습니다. 지금 백엔드 개발자가 하던 반복 작업이 대폭 자동화됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분 항목</th><th style="text-align:left;">지 금 (기존 수작업 백엔드 개발)</th><th style="text-align:left;">SYNCBOOT 도입 후</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>CRUD API 개발</strong></td><td style="text-align:left;">Controller, Service, DTO, Mapper를 손으로 일일이 코딩</td><td style="text-align:left;"><strong>로우코드 엔진이 Entity 정의만으로 풀스택 코드 즉시 생성</strong></td></tr><tr><td style="text-align:left;"><strong>DB 스키마 변경</strong></td><td style="text-align:left;">개발자가 DDL을 수기 작성하고 수동 마이그레이션 실행</td><td style="text-align:left;"><strong>AI가 3-File 표준 DDL을 자동 설계하고 원클릭 승인 반영</strong></td></tr><tr><td style="text-align:left;"><strong>권한 및 멀티테넌트</strong></td><td style="text-align:left;">테넌트 분리 및 RBAC 로직을 매번 처음부터 자체 구축</td><td style="text-align:left;"><strong>엔터프라이즈급 멀티테넌트 및 세분화 IAM 기본 탑재</strong></td></tr><tr><td style="text-align:left;"><strong>대용량 배치 처리</strong></td><td style="text-align:left;">Quartz/Spring Batch 코드를 수작업으로 복잡하게 작성</td><td style="text-align:left;"><strong>GUI 기반 비주얼 스케줄러 및 자동 재시도/Skip 제어</strong></td></tr><tr><td style="text-align:left;"><strong>서버 로그 추적</strong></td><td style="text-align:left;">장애 발생 시 터미널 접속 후 여러 서버의 로그 수동 grep</td><td style="text-align:left;"><strong>에이전트가 클러스터 서버 로그를 직접 수집하여 AI 진단</strong></td></tr><tr><td style="text-align:left;"><strong>프레임워크 표준화</strong></td><td style="text-align:left;">프로젝트마다 개발자 취향대로 구조가 달라 유지보수 난항</td><td style="text-align:left;"><strong>LangChain4j + Spring Boot + Vue3 전사 단일 표준화</strong></td></tr></tbody></table><hr><h2 id="slide-16-16-·-기-대-효-과-지-금-말-씀-드-릴-수-있-는-것" tabindex="-1">[Slide 16] 16 · 기 대 효 과 (지 금 말 씀 드 릴 수 있 는 것) <a class="header-anchor" href="#slide-16-16-·-기-대-효-과-지-금-말-씀-드-릴-수-있-는-것" aria-label="Permalink to “[Slide 16] 16 · 기 대 효 과 (지 금  말 씀  드 릴  수  있 는  것)”">​</a></h2><h3 id="효과는-직접-써-보고-확인하시면-됩니다" tabindex="-1"><strong>효과는 직접 써 보고 확인하시면 됩니다.</strong> <a class="header-anchor" href="#효과는-직접-써-보고-확인하시면-됩니다" aria-label="Permalink to “효과는 직접 써 보고 확인하시면 됩니다.”">​</a></h3><p>몇 퍼센트 줄어든다는 숫자를 먼저 말씀드리지 않겠습니다. 지금 분명히 말할 수 있는 것과, 직접 써 봐야 알 수 있는 것을 나눠 적었습니다.</p><h4 id="📌-지금-확실한-것" tabindex="-1">📌 지금 확실한 것 <a class="header-anchor" href="#📌-지금-확실한-것" aria-label="Permalink to “📌 지금 확실한 것”">​</a></h4><ul><li>반복적인 CRUD API 개발 공수가 70% 이상 절감됩니다.</li><li>3-File 표준 스키마 적용으로 DB 마이그레이션 실수가 사라집니다.</li><li>멀티테넌트 및 RBAC 권한 구축 기간이 수개월에서 수일로 단축됩니다.</li><li>장애 발생 시 분산 서버 로그 수집 및 원인 파악이 즉각 이루어집니다.</li><li>검증된 엔터프라이즈 아키텍처로 시스템 안정성이 대폭 향상됩니다.</li></ul><h4 id="🔍-써-보고-재야-아는-것" tabindex="-1">🔍 써 보고 재야 아는 것 <a class="header-anchor" href="#🔍-써-보고-재야-아는-것" aria-label="Permalink to “🔍 써 보고 재야 아는 것”">​</a></h4><ul><li>신규 비즈니스 서비스 런칭까지 걸리는 실제 백엔드 개발 기간</li><li>DB 스키마 변경 시 발생하는 런타임 에러 건수의 감소율</li><li>분산 서버 장애 발생 시 평균 복구 시간(MTTR)의 단축 폭</li><li>로우코드 코드 생성을 통해 개발팀이 절감한 총 엔지니어링 시간</li></ul><hr><h2 id="slide-17-17-·-다-른-점-기-존-도-구-와-의-차-이" tabindex="-1">[Slide 17] 17 · 다 른 점 (기 존 도 구 와 의 차 이) <a class="header-anchor" href="#slide-17-17-·-다-른-점-기-존-도-구-와-의-차-이" aria-label="Permalink to “[Slide 17] 17 · 다 른  점 (기 존  도 구 와 의  차 이)”">​</a></h2><h3 id="단순한-코드-생성기나-orm-도구와는-차원이-다릅니다" tabindex="-1"><strong>단순한 코드 생성기나 ORM 도구와는 차원이 다릅니다.</strong> <a class="header-anchor" href="#단순한-코드-생성기나-orm-도구와는-차원이-다릅니다" aria-label="Permalink to “단순한 코드 생성기나 ORM 도구와는 차원이 다릅니다.”">​</a></h3><p>코드만 몇 줄 만들어주는 도구가 아니라, 도메인 맥락을 인지하여 런타임 데이터 운영과 보안, 스키마 거버넌스까지 책임지는 백엔드 플랫폼입니다.</p><ol><li><strong>시스템 도메인 컨텍스트를 스스로 인지합니다</strong>: 자신이 동작 중인 구체적인 서비스의 비즈니스 목적을 이해하고 안전한 범위 내에서만 CRUD를 수행합니다.</li><li><strong>안전한 3-File DB 스키마 표준을 강제합니다</strong>: init/domain/sample 3-File 구조와 개발자 승인 절차를 통해 스키마 무결성을 보장합니다.</li><li><strong>표준 MCP 도구를 탑재하여 A2A 통신을 완벽 지원합니다</strong>: SyncVerse 및 타 에이전트와 Model Context Protocol로 연결되어 자가치유 파이프라인에 참여합니다.</li><li><strong>분산 클러스터 서버 로그를 자율 수집합니다</strong>: 중앙 로깅 인프라가 다운되어도 에이전트가 로컬 서버 로그를 직접 추출하여 전달합니다.</li><li><strong>운영 데이터와 소스코드 수정을 엄격히 분리합니다</strong>: 런타임 에이전트는 소스를 건드리지 않고, 코드 수정은 SyncVerse의 SDK 코딩 에이전트에 위임합니다.</li></ol><hr><h2 id="slide-18-18-·-도-입-방-안-시-작-하-는-법-·-마-무-리" tabindex="-1">[Slide 18] 18 · 도 입 방 안 (시 작 하 는 법 · 마 무 리) <a class="header-anchor" href="#slide-18-18-·-도-입-방-안-시-작-하-는-법-·-마-무-리" aria-label="Permalink to “[Slide 18] 18 · 도 입  방 안 (시 작 하 는  법  ·  마 무 리)”">​</a></h2><h3 id="단일-업무-도메인-모듈-하나로-시작합니다" tabindex="-1"><strong>단일 업무 도메인 모듈 하나로 시작합니다.</strong> <a class="header-anchor" href="#단일-업무-도메인-모듈-하나로-시작합니다" aria-label="Permalink to “단일 업무 도메인 모듈 하나로 시작합니다.”">​</a></h3><p>한 번에 모든 레거시 백엔드를 전환하지 않습니다. 신규 도메인이나 서브시스템 하나를 골라 구축해 보고 점진적으로 확대합니다.</p><h3 id="첫-째-2-4주-기반-프레임워크-셋업-도메인-선정" tabindex="-1">첫 째 (2 ~ 4주): 기반 프레임워크 셋업 &amp; 도메인 선정 <a class="header-anchor" href="#첫-째-2-4주-기반-프레임워크-셋업-도메인-선정" aria-label="Permalink to “첫 째 (2 ~ 4주): 기반 프레임워크 셋업 &amp; 도메인 선정”">​</a></h3><ul><li>대상 도메인(예: 회원, 주문, 정산) 한 개 선정</li><li>SyncBoot 스타터 패키지 및 3-File DB 스키마 셋업</li><li>멀티테넌트 및 RBAC 기본 권한 체계 연동</li></ul><h3 id="둘-째-4-8주-로우코드-api-가동-시범-운영" tabindex="-1">둘 째 (4 ~ 8주): 로우코드 API 가동 &amp; 시범 운영 <a class="header-anchor" href="#둘-째-4-8주-로우코드-api-가동-시범-운영" aria-label="Permalink to “둘 째 (4 ~ 8주): 로우코드 API 가동 &amp; 시범 운영”">​</a></h3><ul><li>로우코드 엔진으로 도메인 CRUD API 및 화면 생성</li><li>도메인 에이전트의 데이터 조작 및 로그 수집 검증</li><li>개발 생산성 향상률 및 성능 벤치마크 측정</li></ul><h3 id="셋-째-이후-전사-백엔드-프레임워크-표준화" tabindex="-1">셋 째 (이후): 전사 백엔드 프레임워크 표준화 <a class="header-anchor" href="#셋-째-이후-전사-백엔드-프레임워크-표준화" aria-label="Permalink to “셋 째 (이후): 전사 백엔드 프레임워크 표준화”">​</a></h3><ul><li>사내 타 백엔드 마이크로서비스로 프레임워크 확대</li><li>SyncVerse 중앙 관제탑과 MCP A2A 파이프라인 연결</li><li>전사 데이터 리니지 및 감사 컴플라이언스 체계 완성</li></ul><blockquote><p><strong>이미 쓰고 계신 인프라와 연결</strong>: 데이터베이스 (MySQL / PostgreSQL / Oracle) · 캐시 (Redis Cluster) · 메시징 (Kafka / RabbitMQ) · 중앙관제 (SyncVerse MCP)</p></blockquote><hr><h2 id="slide-19-마무리-end-slide" tabindex="-1">[Slide 19] 마무리 (End Slide) <a class="header-anchor" href="#slide-19-마무리-end-slide" aria-label="Permalink to “[Slide 19] 마무리 (End Slide)”">​</a></h2><h1 id="감사합니다" tabindex="-1"><strong>감사합니다</strong> <a class="header-anchor" href="#감사합니다" aria-label="Permalink to “감사합니다”">​</a></h1><h3 id="syncboot-—-ai-기반-엔터프라이즈-백엔드-로우코드-풀스택-프레임워크" tabindex="-1"><strong>SyncBoot — AI 기반 엔터프라이즈 백엔드 &amp; 로우코드 풀스택 프레임워크</strong> <a class="header-anchor" href="#syncboot-—-ai-기반-엔터프라이즈-백엔드-로우코드-풀스택-프레임워크" aria-label="Permalink to “SyncBoot — AI 기반 엔터프라이즈 백엔드 &amp; 로우코드 풀스택 프레임워크”">​</a></h3><p>엠파시 솔루션개발팀 | <strong>Empasy.</strong></p>',117)])])}const b=l(i,[["render",n]]);export{p as __pageData,b as default};
